/// A tree's untracked area, <state>/untracked/<tree>/ (mode 0700, made on first use): the tree's files the rules leave out, reached only beneath it (openat2 RESOLVE_BENEATH|NO_SYMLINKS|NO_MAGICLINKS, never following a link).
pub struct UntrackedArea { /* dir: crate::confined::Dir, tree: TreeId */ }
impl UntrackedArea {
    pub fn tree(&self) -> TreeId;
    pub fn dir(&self) -> &crate::confined::Dir;
    /// `path`'s parent directory opened O_PATH|O_DIRECTORY beneath the area, and its last name: where a passthrough *at call acts.
    pub fn parent(&self, path: &str) -> std::io::Result<(std::os::fd::OwnedFd, String)>;
    /// lstat of `path` ("" is the area itself); None when nothing is there.
    pub fn stat(&self, path: &str) -> std::io::Result<Option<rustix::fs::Stat>>;
    /// Makes each missing directory above `path` as a container standing for the tracked directory there: mode from meta_of(dir), and its owner when the process may chown (crate privileges as the view's).
    pub fn containers(&self, path: &str, meta_of: &mut dyn FnMut(&str) -> Option<Meta>) -> std::io::Result<()>;
    /// `dir`'s entries sorted by name, without . and ..; names that are not UTF-8 are left out.
    pub fn entries(&self, dir: &str) -> std::io::Result<Vec<(String, rustix::fs::FileType)>>;
    /// Puts `len` bytes of `src` at `path` with meta's mode and owner (a link when meta.kind is Symlink, `src` holding its target), replacing any non-directory there:
    /// written under <state>/untracked/.staging/, fsynced, then renamed into place. The containers above `path` must exist.
    pub fn place(&self, path: &str, src: &mut dyn std::io::Read, len: u64, meta: Meta) -> std::io::Result<()>;
}
